    // Shared memory for tiles of A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    // Block-wide row and column indices for C
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // Thread-wide row and column indices within the block
    int row = threadIdx.y;
    int col = threadIdx.x;

    // Global row and column indices for C
    int globalRow = blockRow * BLOCK_SIZE + row;
    int globalCol = blockCol * BLOCK_SIZE + col;

    float Cvalue = 0;

    // Loop over the tiles of A and B that contribute to the current C tile
    for (int tile = 0; tile < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; ++tile) {
        // Load tile from global memory to shared memory
        // As tile
        int A_row_global = blockRow * BLOCK_SIZE + row;
        int A_col_global = tile * BLOCK_SIZE + col;
        if (A_row_global < N && A_col_global < N) {
            As[row][col] = A[A_row_global * N + A_col_global];
        } else {
            As[row][col] = 0.0f; // Pad with zeros if out of bounds
        }

        // Bs tile
        int B_row_global = tile * BLOCK_SIZE + row;
        int B_col_global = blockCol * BLOCK_SIZE + col;
        if (B_row_global < N && B_col_global < N) {
            Bs[row][col] = B[B_row_global * N + B_col_global];
        } else {
            Bs[row][col] = 0.0f; // Pad with zeros if out of bounds
